component.css:
.cine {--gold: #e8c37a;--silver: #b9c4cf;position: relative;width: 100%;max-width: 600px;margin: 4px auto;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;}
.cine-frame {position: relative;width: 100%;aspect-ratio: 16 / 9;container-type: size;background: #05070c;border-radius: 10px;overflow: hidden;box-shadow: 0 6px 24px #0d142055, inset 0 0 0 1px #ffffff14;}
.cine-holes {position: absolute; left: 0; right: 0; height: 7.5%; z-index: 5; background: #05070c; background-image: radial-gradient(circle at center, #ffffff2e 0 22%, transparent 26%); background-size: 9% 200%; background-repeat: repeat-x; pointer-events: none;}
.cine-holes--t { top: 0; background-position: 0 120%; }
.cine-holes--b { bottom: 0; background-position: 0 -20%; }
.cine-imgwrap { position: absolute; inset: 7.5% 0; overflow: hidden; background: #0a0f18; }
.cine-imgwrap img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity .8s; }
.cine-imgwrap img.is-in { opacity: 1; animation: cineKb 26s ease-in-out infinite alternate; }
@keyframes cineKb { 0% { transform: scale(1.02) translate(0, 0); } 50% { transform: scale(1.09) translate(-1.2%, .8%); } 100% { transform: scale(1.03) translate(1%, -.6%); } }
.cine-load { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; z-index: 3; background: #0a0f18; transition: opacity .5s; }
.cine-load.is-off { opacity: 0; pointer-events: none; }
.cine-load span { width: 13%; aspect-ratio: 1; border-radius: 50%; border: 2px solid #ffffff26; border-top-color: var(--silver); animation: cineSpin 1s linear infinite; }
@keyframes cineSpin { to { transform: rotate(360deg); } }
.cine-grain { position: absolute; inset: -50%; z-index: 4; pointer-events: none; opacity: .12; background-image: repeating-conic-gradient(#fff 0% .0001%, transparent .0002% .0004%); background-size: 42% 42%; animation: cineGrain .6s steps(4) infinite; mix-blend-mode: overlay; }
@keyframes cineGrain { 0% { transform: translate(0,0); } 25% { transform: translate(-3%,2%); } 50% { transform: translate(2%,-3%); } 75% { transform: translate(-2%,-2%); } 100% { transform: translate(0,0); } }
.cine-vig { position: absolute; inset: 0; z-index: 4; pointer-events: none; background: radial-gradient(ellipse at center, transparent 52%, #05070c99 100%); }
.cine-fallback { position: absolute; inset: 0; z-index: 2; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6%; background: linear-gradient(160deg, #101a2c, #1d2436 45%, #0a0f18); }
.cine-fallback b { font-size: 5.5cqh; letter-spacing: .3em; color: #e8c37a; }
.cine-fallback i { font-style: normal; font-size: 3cqh; color: #8fa1b8; letter-spacing: .2em; }
.cine-fallback.is-off { display: none; }
.cine-topbar { position: absolute; top: 9.5%; left: 0; right: 0; z-index: 6; display: flex; justify-content: space-between; align-items: center; padding: 0 2.6%; pointer-events: none; }
.cine-day { font-size: 3.4cqh; font-weight: 700; letter-spacing: .12em; color: #fff; text-shadow: 0 1px 6px #000c; background: #05070c99; padding: .5cqh 1.4cqw; border-radius: 4px; border-left: 3px solid var(--gold); }
.cine-live { display: flex; align-items: center; gap: 1%; font-size: 2.5cqh; letter-spacing: .18em; color: #ffffffd9; text-shadow: 0 1px 4px #000c; }
.cine-live i { width: 1.6cqh; height: 1.6cqh; border-radius: 50%; background: #ff5a4e; animation: cineBlink 1.4s ease-in-out infinite; margin-right: .6cqw; }
@keyframes cineBlink { 50% { opacity: .25; } }
.cine-badge { position: absolute; top: 20%; right: 2.4%; z-index: 6; font-size: 2.5cqh; letter-spacing: .1em; color: #1a1408; background: linear-gradient(135deg, #f2d493, #d9a94f); padding: .7cqh 1.5cqw; border-radius: 4px; font-weight: 700; box-shadow: 0 2px 10px #0009; display: none; }
.cine-badge.is-cg { display: block; }
.cine-badge.is-gen { display: block; color: #0d1420; background: linear-gradient(135deg, #dbe4ec, #a9b8c6); }
.cine-cap { position: absolute; left: 0; right: 0; bottom: 7.5%; z-index: 6; display: flex; flex-direction: column; gap: .8cqh; padding: 6cqh 3cqw 1.8cqh; background: linear-gradient(#00000000, #000000d9); pointer-events: none; }
.cine-cap b { font-size: 3.8cqh; color: #fff; letter-spacing: .06em; text-shadow: 0 1px 6px #000d; }
.cine-cap span { font-size: 2.7cqh; line-height: 1.5; color: #ffffffbf; overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.cine-brand { position: absolute; bottom: 1.6%; right: 2.6%; z-index: 7; font-size: 2cqh; letter-spacing: .2em; color: #ffffff7a; pointer-events: none; }

component.script:
"use strict";(() => {
var SL = String.fromCharCode(47);
var PROT = ":" + SL + SL;
var root = document.getElementById("cineRoot");
if (!root) return;
var byId = i => document.getElementById(i);
var IMG = ["https:", "", "origin.picgo.net", "2026", "10", "20", ""].join(SL);
var FILES = {
A1: "10000861656376ba6773ac62ec.png", A2: "1000086163dcfbc61b06adb774.png", A3: "1000086316355c5a89b233f72d.png", A4: "1000086164e22142db4f5769ff.png", A5: "100008631581f6e00748abf5bc.png", A6: "100008631421daf42150a16ba6.png", A7: "1000086317a5febdc653a56462.png", A8: "100008616645374a90dddc3f8a.png",
B1: "1000086155d8aa3fecd389ec54.jpg", B2: "1000086156d8633bbaf3cfd25e.jpg", B3: "10000861576c64db2b8c74ebb7.jpg", B4: "100008615814948ac4a04473c3.jpg", B5: "10000861591cc874792df16809.jpg", B6: "1000086160a6cdc10868c7ae75.jpg", B7: "100008616173b1ddef0cf8aae9.jpg", B8: "10000861629cf75370e4725061.jpg",
C1: "1000086169c9bc528f1c2dc532.jpg", C2: "10000861684b450f1b0b48bee8.jpg", C3: "10000861675f82e63036932ba1.jpg", C4: "100008617100c1ef26ff80a6f4.jpg", C5: "1000086173df523ad44c60f707.jpg", C6: "1000086174bd29680c472147a3.jpg", C7: "1000086172fee03b69aa7a02a2.jpg", C8: "10000861703fe7f44288ca5b06.jpg"
};
var CAPS = {
A1: "在车上 · 那个时", A2: "车后座 · 睡觉", A3: "旅馆 · 洗澡时", A4: "睡着时", A5: "篝火旁", A6: "主驾驶 · 睡着", A7: "加油站", A8: "尝试 · 那个时",
B1: "车上 · 喝水", B2: "下车了", B3: "摘花", B4: "店门口 · 摆pose", B5: "放杯 · 耍帅", B6: "露营 · 烧烤", B7: "太热了 · 脱上衣", B8: "刚穿上衣服",
C1: "开车 · 刚上路", C2: "篝火旁的夜晚", C3: "停车休息 · 望天空", C4: "自己 · 那个时", C5: "野外 · 看星星", C6: "早上 · 刚起床", C7: "傍晚 · 下车休息", C8: "旅馆 · 疲惫的脚"
};
var BAD = new RegExp("\\b(\\d*(?:man|men|woman|women|boy|boys|girl|girls|guy|guys|lady|ladies|male|female|person|people|human|humans|character|characters|protagonist|hero|heroine|anthro|furry|kemono|beast|portrait|he|she)\\d*)\\b", "i");
var CN = new RegExp("男人|男孩|女人|女孩|人物|角色|兽人|人类|少年|少女");
var NOH = ",no%20humans,no%20people,no%20characters,no%20anthro,scenery%20only,empty%20landscape";
var FALLBACK = "empty%20desert%20highway%20at%20dusk,lone%20car%20parked,wide%20shot,cinematic,scenery";
var stripUrl = s => {
  var m = s.indexOf(PROT);
  if (m < 0) return s;
  var rest = s.slice(m + 3);
  var e = rest.indexOf(SL);
  return e >= 0 ? rest.slice(e + 1) : "";
};
var clean = p => {
  var tags = stripUrl(p || "").split(",").map(t => t.trim().split(" ").join("%20")).filter(Boolean);
  var keep = tags.filter(t => {
    var plain = t.split("%20").join(" ");
    return !BAD.test(plain) && !CN.test(plain);
  });
  return keep.length ? keep.join(",") : FALLBACK;
};
var attr = k => (root.getAttribute("data-" + k) || "").trim();
var rawCode = attr("code").toUpperCase().split(" ").join("").split("-").join("");
var code = (rawCode.length === 2 && "ABC".indexOf(rawCode.charAt(0)) >= 0 && rawCode.charAt(1) >= "1" && rawCode.charAt(1) <= "8") ? rawCode : "";
var prompt = attr("prompt");
var img = byId("cineImg"), load = byId("cineLoad"), fall = byId("cineFall"), badge = byId("cineBadge");
byId("cineTitle").textContent = attr("title") || (code && CAPS[code]) || "";
byId("cineNote").textContent = attr("note");
var dayRaw = attr("day");
var dayEl = byId("cineDay");
var dayNum = "";
if (dayRaw) {
  var dd = dayRaw.toUpperCase().split(" ").join("");
  if (dd.charAt(0) === "D") {
    var rest = dd.slice(1);
    var num = "";
    for (var i = 0; i < rest.length && i < 2; i++) {
      var c = rest.charAt(i);
      if (c >= "0" && c <= "9") num += c; else break;
    }
    if (num) dayNum = num;
  }
  dayEl.textContent = dayNum ? "DAY " + dayNum : dayRaw;
} else {
  dayEl.style.display = "none";
}
var src = "";
if (code && FILES[code]) {
  src = IMG + FILES[code];
  badge.textContent = code + " · 正式CG已收录";
  badge.className = "cine-badge is-cg";
  var KEY = "都CG";
  var readLocal = () => { try { return localStorage.getItem(KEY) || ""; } catch (e) { return ""; } };
  var merge = v => {
    var seen = {};
    var s = (v || "") + readLocal();
    for (var i = 0; i + 1 < s.length; i++) {
      var a = s.charAt(i), b = s.charAt(i + 1);
      if (a >= "A" && a <= "C" && b >= "1" && b <= "8") seen[a + b] = 1;
    }
    seen[code] = 1;
    return Object.keys(seen).sort().join("");
  };
  var done = merged => {
    try { localStorage.setItem(KEY, merged); } catch (e) {}
    if (typeof saveToLocal === "function") Promise.resolve(saveToLocal(KEY, merged)).catch(() => {});
  };
  var p;
  try {
    p = typeof readFromLocal === "function" ? Promise.resolve(readFromLocal(KEY)).catch(readLocal) : Promise.resolve(readLocal());
  } catch (e) { p = Promise.resolve(readLocal()); }
  p.then(v => done(merge(v))).catch(() => done(merge(readLocal())));
} else if (prompt) {
  var PU = ["https:", "", "image.pollinations.ai", "prompt", ""].join(SL);
  src = PU + clean(prompt) + NOH + "?width=960&height=540&nologo=true&seed=" + Math.floor(Math.random() * 999999);
  badge.textContent = "场景速写 · AI";
  badge.className = "cine-badge is-gen";
}
if (src) {
  var retried = false;
  img.addEventListener("load", () => {
    img.classList.add("is-in");
    load.classList.add("is-off");
    fall.classList.add("is-off");
  });
  img.addEventListener("error", () => {
    if (retried) {
      load.classList.add("is-off");
      fall.classList.remove("is-off");
    } else {
      retried = true;
      img.src = src + (src.indexOf("?") >= 0 ? "&" : "?") + "r=1";
    }
  });
  img.src = src;
} else {
  load.classList.add("is-off");
  fall.classList.remove("is-off");
  badge.style.display = "none";
  dayEl.style.display = "none";
  byId("cineLive").style.display = "none";
  byId("cineCap").style.display = "none";
}
})();
